-- Tables only the conformance suite's tests use (../sqlite/conformance.sql), applied after the fixture schema.
CREATE TABLE stamps (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT, seconds BIGINT, milliseconds BIGINT);

CREATE TABLE entries (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);

-- TEXT, as an app may keep JSON: a cell that isn't JSON can then be stored, and must fail to load.
CREATE TABLE json_docs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, folder_id BIGINT, settings TEXT, secret TEXT);

CREATE TABLE json_folders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY);

CREATE TABLE guarded_stamps (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, seconds BIGINT, milliseconds BIGINT, mapped_at BIGINT, iso TIMESTAMPTZ);

-- meta is JSON, which keeps its text as written, as a raw query in its tests reads it (jsonb-text).
CREATE TABLE typed_posts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT, published_at TIMESTAMPTZ, seconds BIGINT, milliseconds BIGINT, featured BOOLEAN, rating BIGINT, score DOUBLE PRECISION, meta JSON, secret TEXT);

CREATE TABLE typed_samples (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, label TEXT, enabled BOOLEAN, settings JSONB, stamp TIMESTAMPTZ, secret TEXT);
